import{_ as e,o,c as r,a6 as a}from"./chunks/framework.BJFjZBwW.js";const d=JSON.parse('{"title":"Participate in OpenMQTTGateway","description":"","frontmatter":{},"headers":[],"relativePath":"participate/index.md","filePath":"participate/index.md","lastUpdated":1774872020000}'),n={name:"participate/index.md"};function i(s,t,h,p,c,l){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="participate-in-openmqttgateway" tabindex="-1">Participate in OpenMQTTGateway <a class="header-anchor" href="#participate-in-openmqttgateway" aria-label="Permalink to &quot;Participate in OpenMQTTGateway&quot;">​</a></h1><p>OpenMQTTGateway is community-driven: every feature, bug fix, and doc improvement comes from contributors like you. Whether you want to add support for a new sensor, fix a bug, improve documentation, or just help others—there&#39;s a place for you here.</p><h2 id="choose-your-path" tabindex="-1">Choose your path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose your path&quot;">​</a></h2><h3 id="🚀-new-to-the-project-start-here" tabindex="-1">🚀 New to the project? Start here <a class="header-anchor" href="#🚀-new-to-the-project-start-here" aria-label="Permalink to &quot;🚀 New to the project? Start here&quot;">​</a></h3><p><a href="./quick_start.html"><strong>Quick Start Guide</strong></a> walks you through setting up your development environment, building firmware, and previewing the docs. It covers PlatformIO, VS Code, terminal workflows, and troubleshooting. Perfect if you&#39;re new to ESP32/ESP8266 development or just want to get your hands dirty quickly.</p><p><strong>What you&#39;ll learn:</strong> Installing tools · Building firmware · Flashing boards · Running tests · Working with the docs</p><hr><h3 id="💻-ready-to-contribute-code" tabindex="-1">💻 Ready to contribute code? <a class="header-anchor" href="#💻-ready-to-contribute-code" aria-label="Permalink to &quot;💻 Ready to contribute code?&quot;">​</a></h3><p><a href="./development.html"><strong>Development Contributions</strong></a> covers the contribution workflow: naming conventions, code quality checks, testing on multiple boards, and opening pull requests. This is your checklist before submitting code.</p><p><strong>What you&#39;ll find:</strong> PR workflow · Naming rules (ZgatewayXXX, ZsensorYYY) · QA automation · DCO · CI/CD integration</p><hr><h3 id="🔌-adding-a-new-protocol-or-device" tabindex="-1">🔌 Adding a new protocol or device? <a class="header-anchor" href="#🔌-adding-a-new-protocol-or-device" aria-label="Permalink to &quot;🔌 Adding a new protocol or device?&quot;">​</a></h3><p><a href="./adding-protocols.html"><strong>Adding Protocols</strong></a> explains how to integrate RF, IR, or BLE devices. Most protocol work happens upstream (RCSwitch, Pilight, IRRemoteESP8266, Theengs Decoder), and this guide shows you how to wire it into OMG.</p><p><strong>What you&#39;ll learn:</strong> Upstream contribution · Protocol integration · Testing decoders · Payload validation</p><hr><h3 id="💬-join-the-community" tabindex="-1">💬 Join the community <a class="header-anchor" href="#💬-join-the-community" aria-label="Permalink to &quot;💬 Join the community&quot;">​</a></h3><p><a href="./community.html"><strong>Community Participation</strong></a> is where you ask questions, share your projects, and help others. The forum is the first stop for feature requests, debugging help, and general IoT/home automation discussion.</p><p><strong>What you can do:</strong> Ask questions · Share builds · Propose features · Help newcomers</p><hr><h3 id="❤️-support-the-project" tabindex="-1">❤️ Support the project <a class="header-anchor" href="#❤️-support-the-project" aria-label="Permalink to &quot;❤️ Support the project&quot;">​</a></h3><p><a href="./support.html"><strong>Supporting the Project</strong></a> lists all the ways you can help beyond code: answering forum questions, improving docs, purchasing Theengs products, sponsoring developers, or creating content about your OMG setup.</p><p><strong>How you can help:</strong> Forum support · Documentation · Sponsorship · Content creation</p><hr><div class="tip custom-block"><p class="custom-block-title">Not sure where to start?</p><ul><li><strong>First time here?</strong> → <a href="./quick_start.html">Quick Start</a></li><li><strong>Have a fix or feature ready?</strong> → <a href="./development.html">Development contributions</a></li><li><strong>Need help or want to discuss?</strong> → <a href="./community.html">Community</a></li></ul></div>',24)])])}const m=e(n,[["render",i]]);export{d as __pageData,m as default};
